/** FAQ: раскрывающиеся подробные инструкции по приложению. */
@Composable
fun FaqScreen(onBack: () -> Unit) {
    var open by remember { mutableStateOf<String?>(null) }

    Column(Modifier.fillMaxSize().padding(16.dp)) {
        Row(Modifier.fillMaxWidth(), horizontalArrangement = androidx.compose.foundation.layout.Arrangement.SpaceBetween) {
            TextButton(onClick = onBack) { Text("← Назад") }
            Text("FAQ — как пользоваться", style = MaterialTheme.typography.titleLarge)
        }
        Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState())) {
            FAQ_ITEMS.forEach { item ->
                val isOpen = open == item.q
                Card(Modifier.fillMaxWidth().padding(vertical = 4.dp)
                    .clickable { open = if (isOpen) null else item.q }) {
                    Column(Modifier.padding(14.dp)) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Text(item.q, style = MaterialTheme.typography.titleSmall,
                                modifier = Modifier.weight(1f))
                            Text(if (isOpen) "▲" else "▼",
                                style = MaterialTheme.typography.bodySmall)
                        }
                        if (isOpen) {
                            Spacer(Modifier.height(6.dp))
                            Text(item.a, style = MaterialTheme.typography.bodyMedium)
                        }
                    }
                }
            }
            Spacer(Modifier.height(24.dp))
        }
    }
}
